CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.conduct_metrics
COMMENT 'Conduct KPIs over complaints - volumes, uphold rate, ombudsman-referral rate and redress, by category and outcome. The customer-fairness scoreboard alongside the fair-value view. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_conduct.complaint

dimensions:
  - name: complaint_category_code
    expr: complaint_category_code
  - name: complaint_outcome_code
    expr: complaint_outcome_code
  - name: received_month
    expr: DATE_TRUNC('MONTH', received_date)

measures:
  - name: complaint_count
    expr: COUNT(complaint_id)
  - name: upheld_count
    expr: COUNT(CASE WHEN complaint_outcome_code IN ('UPHELD', 'PARTIAL') THEN complaint_id END)
  - name: uphold_rate
    expr: COUNT(CASE WHEN complaint_outcome_code IN ('UPHELD', 'PARTIAL') THEN complaint_id END) / NULLIF(COUNT(complaint_id), 0)
  - name: fos_referred_count
    expr: COUNT(CASE WHEN fos_referred THEN complaint_id END)
  - name: total_redress
    expr: SUM(redress_amount)
$$;
